import YabCore

public enum SkipReason: Equatable, Sendable {
    case concealed, ignoredApp(String), remoteDisabled
}

public enum CaptureDecision: Equatable, Sendable {
    case capture(DeviceKind), skip(SkipReason)
}

/// Decides whether a pasteboard change is recorded. Honors the nspasteboard.org
/// markers apps use for secrets and throwaway data, and the user's ignore list.
public struct CaptureFilter: Sendable {
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    ]
    /// Marks content that arrived via Universal Clipboard from another device.
    public static let remoteClipboardType = "com.apple.is-remote-clipboard"

    public var ignoredBundleIDs: Set<String> = ["com.apple.keychainaccess", "com.apple.Passwords"]
    public var ignoreConcealed = true
    public var captureRemote = true

    public init() {}

    public func evaluate(types: Set<String>, source: SourceApp?) -> CaptureDecision {
        if ignoreConcealed, !types.isDisjoint(with: Self.concealedTypes) { return .skip(.concealed) }
        if let source, ignoredBundleIDs.contains(source.bundleID) { return .skip(.ignoredApp(source.bundleID)) }
        if types.contains(Self.remoteClipboardType) {
            return captureRemote ? .capture(.remote) : .skip(.remoteDisabled)
        }
        return .capture(.local)
    }
}
